@@ -0,0 +1,46 @@
+package com.example.contact;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+
+import com.vaadin.flow.server.VaadinSession;
+
+/**
+ * Keeps the messages that have been sent, newest first.
+ *
+ * The messages live in the {@link VaadinSession}, so they outlive a single view
+ * instance: leaving the contact view and coming back still shows them.
+ */
+public class MessageStore implements Serializable {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    /**
+     * Returns the store of the current session, creating it on first use.
+     */
+    public static MessageStore getInstance() {
+        VaadinSession session = VaadinSession.getCurrent();
+        if (session == null) {
+            // No session (plain unit test); a throw-away store is good enough.
+            return new MessageStore();
+        }
+        MessageStore store = session.getAttribute(MessageStore.class);
+        if (store == null) {
+            store = new MessageStore();
+            session.setAttribute(MessageStore.class, store);
+        }
+        return store;
+    }
+
+    public synchronized void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    /**
+     * The messages sent so far, newest first.
+     */
+    public synchronized List<ContactMessage> getMessages() {
+        return new ArrayList<>(messages);
+    }
+}
