+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+/**
+ * The same behaviour, checked in a real browser.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private GridElement grid() {
+        return GridElement.get(page);
+    }
+
+    private Locator link(String text) {
+        return page.getByRole(AriaRole.LINK,
+                new Page.GetByRoleOptions().setName(text).setExact(true));
+    }
+
+    @Test
+    void contactView_showsHeadingAndEmptyEnabledForm() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+        grid().assertEmpty();
+    }
+
+    @Test
+    void emptyForm_send_showsErrors() {
+        send().click();
+
+        name().assertErrorMessage("Name is required");
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertErrorMessage("Message is required");
+        phone().assertValid();
+        grid().assertEmpty();
+    }
+
+    @Test
+    void invalidEmail_send_showsError() {
+        name().setValue("Jane");
+        email().setValue("nope");
+        message().setValue("Hi");
+        send().click();
+
+        email().assertErrorMessage("Enter a valid e-mail address");
+        grid().assertEmpty();
+        assertEquals("Jane", name().getValue());
+    }
+
+    @Test
+    void validForm_send_notifiesAndListsTheMessage() {
+        name().setValue("Jane");
+        email().setValue("jane@example.com");
+        message().setValue("Hello there");
+        send().click();
+
+        new NotificationElement(page).assertContent("Message sent");
+        grid().assertRowCount(1);
+        grid().assertCellContent(0, 0, "Jane");
+        grid().assertCellContent(0, 1, "Hello there");
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        name().setValue("Jo");
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void enterKey_sends() {
+        name().setValue("Jane");
+        phone().setValue("123456");
+        message().setValue("Hi from the keyboard");
+        name().getInputLocator().press("Enter");
+
+        new NotificationElement(page).assertContent("Message sent");
+        grid().assertRowCount(1);
+    }
+
+    @Test
+    void emptyForm_aboutLinkNavigatesWithoutAsking() {
+        link("About").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertFalse(new DialogElement(page).isVisible());
+    }
+
+    @Test
+    void dirtyForm_aboutLinkAsksFirst_keepEditing() {
+        name().setValue("Jane");
+        link("About").click();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        new DialogElement(page).assertClosed();
+        assertEquals("Jane", name().getValue());
+        assertThat(page.locator("h1")).hasText("Contact");
+    }
+
+    @Test
+    void dirtyForm_browserBackAsksFirst() {
+        // Build up some history: contact -> about -> contact.
+        link("About").click();
+        assertThat(page.locator("h1")).hasText("About");
+        link("Contact").click();
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        name().setValue("Jane");
+        page.goBack();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals("Jane", name().getValue());
+    }
+
+    @Test
+    void sentMessages_surviveLeavingTheView() {
+        name().setValue("Jane");
+        phone().setValue("123456");
+        message().setValue("Hello there");
+        send().click();
+        grid().assertRowCount(1);
+
+        link("About").click();
+        assertThat(page.locator("h1")).hasText("About");
+        link("Contact").click();
+        assertThat(page.locator("h1")).hasText("Contact");
+
+        grid().assertRowCount(1);
+        grid().assertCellContent(0, 0, "Jane");
+        grid().assertCellContent(0, 1, "Hello there");
+    }
+
+    @Test
+    void dirtyForm_aboutLinkAsksFirst_discard() {
+        message().setValue("half written");
+        link("About").click();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
